    state_df['WallTemperature'] = values["_T"][1, :]
    state_df['Cost'] = (
        state_df['Price'] * dt
        * (state_df['HeaterOutput'] * house.Q_heater
           + state_df['CoolingOutput'] / house.Q_cooling)
    )
    return state_df


